{
  "items": [
    {
      "name": "Polynomial.cancelLeads",
      "module_name": "Mathlib.Algebra.Polynomial.CancelLeads",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Ring R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "MonomialOrder.degree_prod_of_regular",
      "module_name": "Mathlib.RingTheory.MvPolynomial.MonomialOrder",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [inst : CommSemiring R] {ι : Type u_3} {P : ι → MvPolynomial σ R}\n  {s : Finset ι}, (∀ i ∈ s, IsRegular (m.leadingCoeff (P i))) → m.degree (∏ i ∈ s, P i) = ∑ i ∈ s, m.degree (P i)"
    },
    {
      "name": "Polynomial.natDegree_cancelLeads_lt_of_natDegree_le_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.CancelLeads",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {p q : Polynomial R},\n  p.natDegree ≤ q.natDegree → 0 < q.natDegree → (p.cancelLeads q).natDegree < q.natDegree"
    },
    {
      "name": "Polynomial.natDegree_cancelLeads_lt_of_natDegree_le_natDegree_of_comm",
      "module_name": "Mathlib.Algebra.Polynomial.CancelLeads",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Ring R] {p q : Polynomial R},\n  p.leadingCoeff * q.leadingCoeff = q.leadingCoeff * p.leadingCoeff →\n    p.natDegree ≤ q.natDegree → 0 < q.natDegree → (p.cancelLeads q).natDegree < q.natDegree"
    },
    {
      "name": "Polynomial.natDegree_prod'",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] (f : ι → Polynomial R),\n  ∏ i ∈ s, (f i).leadingCoeff ≠ 0 → (∏ i ∈ s, f i).natDegree = ∑ i ∈ s, (f i).natDegree"
    }
  ]
}
